<?php
declare(strict_types=1);
require __DIR__ . '/bootstrap.php';
$admin = require_login();

function make_slug(string $title): string { $slug = strtolower(trim(preg_replace('/[^a-z0-9]+/i', '-', $title), '-')); return $slug ?: 'article'; }
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT) ?: null;
$editing = ['id'=>'','title'=>'','slug'=>'','category'=>'','excerpt'=>'','body'=>'','image_path'=>'','image_alt'=>'','meta_description'=>'','status'=>'draft','published_at'=>''];
if ($id) { $query = db()->prepare('SELECT * FROM articles WHERE id = ?'); $query->execute([$id]); $editing = $query->fetch() ?: $editing; }
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $action = $_POST['action'] ?? '';
    if ($action === 'delete') { db()->prepare('DELETE FROM articles WHERE id = ?')->execute([(int)$_POST['id']]); flash('notice','Article removed.'); redirect('articles.php'); }
    $title=trim((string)$_POST['title']); $slug=make_slug(trim((string)$_POST['slug']) ?: $title); $status=$_POST['status']==='published' ? 'published' : 'draft';
    if ($title === '' || trim((string)$_POST['category']) === '' || trim((string)$_POST['excerpt']) === '' || trim((string)$_POST['body']) === '') { flash('notice','Title, category, excerpt and body are required.'); redirect('articles.php' . ($id ? '?id='.$id : '')); }
    try { $uploaded = store_uploaded_image($_FILES['image_path_upload'] ?? null, (int) $admin['id'], trim((string)($_POST['image_alt'] ?? ''))); } catch (RuntimeException $exception) { flash('notice', $exception->getMessage()); redirect('articles.php' . ($id ? '?id='.$id : '')); }
    $imagePath = $uploaded ?? (trim((string)$_POST['image_path']) ?: null);
    $values=[$title,$slug,strtoupper(trim((string)$_POST['category'])),trim((string)$_POST['excerpt']),trim((string)$_POST['body']),$imagePath,trim((string)($_POST['image_alt'] ?? '')),trim((string)($_POST['meta_description'] ?? '')),$status,$status==='published' ? date('Y-m-d H:i:s') : null];
    $live = $status === 'published' ? ' It is live on the Insights page.' : ' It is a draft, so visitors cannot see it yet.';
    try { if ($id) { $values[]=$id; db()->prepare('UPDATE articles SET title=?,slug=?,category=?,excerpt=?,body=?,image_path=?,image_alt=?,meta_description=?,status=?,published_at=COALESCE(published_at, ?),updated_at=CURRENT_TIMESTAMP WHERE id=?')->execute($values); flash('notice','Article updated.' . $live); } else { db()->prepare('INSERT INTO articles (title,slug,category,excerpt,body,image_path,image_alt,meta_description,status,published_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)')->execute($values); flash('notice','Article created.' . $live); } } catch (PDOException $exception) { flash('notice','The slug is already in use. Choose a different slug.'); redirect('articles.php' . ($id ? '?id='.$id : '')); }
    redirect('articles.php');
}
$articles=db()->query('SELECT * FROM articles ORDER BY created_at DESC')->fetchAll(); $pageTitle=$id?'Edit insight':'Insights'; $activePage='articles'; require __DIR__.'/partials/header.php';
?>
<section class="panel"><h2><?= $id ? 'Update insight article' : 'Create insight article' ?></h2><form method="post" class="form-grid" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label class="full">Title <?= formatting_hint() ?><input name="title" value="<?= e($editing['title']) ?>" required></label><label>Web address <span class="hint">Leave blank to create it from the title.</span><input name="slug" value="<?= e($editing['slug']) ?>" placeholder="generated-from-title"></label><label>Category<input name="category" value="<?= e($editing['category']) ?>" placeholder="PROPERTY MARKET INSIGHTS" required></label><label>Status<select name="status"><option value="draft" <?= $editing['status']==='draft'?'selected':'' ?>>Draft</option><option value="published" <?= $editing['status']==='published'?'selected':'' ?>>Published</option></select></label><label class="full">Summary <span class="hint">One or two sentences shown on the Insights page card.</span><textarea name="excerpt" rows="2" required><?= e($editing['excerpt']) ?></textarea></label><label class="full">Article text <?= formatting_hint(true) ?><textarea name="body" rows="14" required><?= e($editing['body']) ?></textarea></label><?= image_picker('image_path', $editing['image_path'] ?: null) ?><label class="full">Image description <span class="hint">Describe what the photo shows, for screen readers and Google.</span><input name="image_alt" value="<?= e($editing['image_alt']) ?>"></label><label class="full">Google description <span class="hint">Optional. If blank, the summary is used.</span><textarea name="meta_description" rows="2" maxlength="300"><?= e($editing['meta_description']) ?></textarea></label><div class="form-actions full"><button class="button" type="submit">Save article</button><?php if($id): ?><a href="articles.php">Cancel</a><?php endif; ?></div></form></section>
<section class="panel"><h2>All articles</h2><?php if(!$articles): ?><p class="empty">No insight articles have been added yet.</p><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Article</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody><?php foreach($articles as $article): ?><tr><td><strong><?= e($article['title']) ?></strong><br><span class="hint"><?= e($article['category']) ?></span></td><td><span class="tag <?= $article['status']==='draft'?'draft':'' ?>"><?= e(ucfirst($article['status'])) ?></span></td><td><?= e($article['updated_at']) ?></td><td><a href="articles.php?id=<?= $article['id'] ?>">Edit</a> · <?php if ($article['status'] === 'published'): ?><a href="<?= e(public_site_url('article.php?slug=' . rawurlencode($article['slug']))) ?>" target="_blank" rel="noopener">View ↗</a> · <?php endif; ?><form class="inline-form" method="post" onsubmit="return confirm('Remove this article?');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= $article['id'] ?>"><button type="submit">Remove</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php require __DIR__.'/partials/footer.php';
